{
  "name": "opencode-gwdg-quota",
  "version": "1.0.5",
  "description": "Show remaining GWDG SAIA API request quota in the OpenCode status bar (TUI) and Desktop pill",
  "type": "module",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/viewv/opencode-gwdg-quota.git"
  },
  "homepage": "https://github.com/viewv/opencode-gwdg-quota#readme",
  "bugs": {
    "url": "https://github.com/viewv/opencode-gwdg-quota/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "gwdg",
    "saia",
    "academic-cloud",
    "quota",
    "rate-limit"
  ],
  "files": [
    "src",
    "dist",
    "README.md",
    "LICENSE"
  ],
  "exports": {
    ".": "./src/index.ts",
    "./tui": "./src/tui.tsx",
    "./rpc": "./src/rpc.ts",
    "./gui-experimental": "./dist/gui-experimental.cjs"
  },
  "scripts": {
    "build": "vite build",
    "watch": "vite build --watch"
  },
  "dependencies": {
    "@opencode/plugin": "latest"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.6.6",
    "@opentui/solid": ">=0.6.6",
    "solid-js": ">=1.9.0"
  },
  "devDependencies": {
    "vite": "^7.0.0",
    "vite-plugin-solid": "^2.11.0"
  }
}
